How can I use Go code to store tree characteristics such as height, leaf shape, and bark texture in a MySQL database? Can you provide an example of how to insert the data into the database and generate a random name for the tree using string formatting in Go code? Additionally, could you provide the Go code for creating a table to store the tree characteristics in the MySQL database?
[Go code]
package main
import (
    "database/sql"
    "fmt"
    "math/rand"
    "time"
    _ "github.com/go-sql-driver/mysql"
)
func main() {
    db, err := sql.Open("mysql", "user:password@tcp(127.0.0.1:3306)/mydatabase")
    if err != nil {
        panic(err.Error())
    }
    defer db.Close()
    // create table to store tree characteristics
    _, err = db.Exec("CREATE TABLE trees (id INT AUTO_INCREMENT PRIMARY KEY, height INT, leaf_shape VARCHAR(255), bark_texture VARCHAR(255))")
    if err != nil {
        panic(err.Error())
    }
    // insert tree data into table
    height := 10
    leafShape := "oval"
    barkTexture := "smooth"
    _, err = db.Exec("INSERT INTO trees (height, leaf_shape, bark_texture) VALUES (?, ?, ?)", height, leafShape, barkTexture)
    if err != nil {
        panic(err.Error())
    }
    // generate random tree name using string formatting
    rand.Seed(time.Now().UnixNano())
    adjectives := []string{"big", "tall", "majestic", "grand", "lofty"}
    nouns := []string{"oak", "maple", "pine", "birch", "cedar"}
    randomAdjective := adjectives[rand.Intn(len(adjectives))]
    randomNoun := nouns[rand.Intn(len(nouns))]
    treeName := fmt.Sprintf("%s %s", randomAdjective, randomNoun)
    fmt.Println(treeName)
}

