import java.util.regex.Matcher;
import java.util.regex.Pattern;
public class HyperboleIdentifier {

    public static void main(String[] args) {
        String text = "I'm so hungry I could eat a horse. My backpack weighs a ton. This book weighs a ton too.";
        String hyperbolePattern = "(?i)\\bso\\b.*?\\b(hungry|thirsty|tired|excited|happy|angry|sad)\\b.*?\\b(could|can)\\b.*?\\b(eat|drink|sleep)\\b.*?\\b(a\\s)?(horse|elephant|whale|mountain)\\b.*?";
        Pattern pattern = Pattern.compile(hyperbolePattern);
        Matcher matcher = pattern.matcher(text);
        while (matcher.find()) {
            System.out.println("Hyperbole found: " + matcher.group());
        }
    }
}
