Creating a visually striking and interactive sculpture in a mobile app can be achieved using SpriteKit, a 2D game engine provided by Apple. The following Swift code can be used to create a sculpture and customize its movements and actions:
```swift
import SpriteKit
class Sculpture: SKSpriteNode {
    // Properties of the sculpture
    var isMoving = false
    var isRotating = false
    var isScaling = false
    // Initialize the sculpture with an image
    init(imageNamed: String) {
        let texture = SKTexture(imageNamed: imageNamed)
        super.init(texture: texture, color: .clear, size: texture.size())
        self.isUserInteractionEnabled = true
    }
    // Handle user touch events
    override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
        isMoving = true
    }
    override func touchesMoved(_ touches: Set<UITouch>, with event: UIEvent?) {
        let touch = touches.first!
        let location = touch.location(in: self.parent!)
        self.position = location
    }
    override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
        isMoving = false
        isRotating = true
    }
    // Update the sculpture's movements and actions
    override func update(_ currentTime: TimeInterval) {
        if isMoving {
            // Move the sculpture in a random direction
            let dx = CGFloat(arc4random_uniform(50)) - 25
            let dy = CGFloat(arc4random_uniform(50)) - 25
            self.position.x += dx
            self.position.y += dy
        }
        if isRotating {
            // Rotate the sculpture continuously
            let rotateAction = SKAction.rotate(byAngle: CGFloat.pi, duration: 1.0)
            let repeatAction = SKAction.repeatForever(rotateAction)
            self.run(repeatAction)
            isRotating = false
            isScaling = true
        }
        if isScaling {
            // Scale the sculpture up and down
            let scaleUpAction = SKAction.scale(to: 1.5, duration: 0.5)
            let scaleDownAction = SKAction.scale(to: 1.0, duration: 0.5)
            let sequenceAction = SKAction.sequence([scaleUpAction, scaleDownAction])
            let repeatAction = SKAction.repeatForever(sequenceAction)
            self.run(repeatAction)
            isScaling = false
        }
    }
}
```
This code defines a `Sculpture` class that extends `SKSpriteNode`. The sculpture is initialized with an image and is set to be user interactive. When the user touches the sculpture, it becomes movable. When the user releases the sculpture, it starts rotating continuously. Finally, the sculpture scales up and down repeatedly.
