// Handle collisions with other objects
func didBegin(_ contact: SKPhysicsContact) {
    let other = contact.bodyA.categoryBitMask == 1 ? contact.bodyB : contact.bodyA
    let dx = self.position.x - other.node!.position.x
    let dy = self.position.y - other.node!.position.y
